---@class UIMainChapterCahpterNode     
---@field ImgSelect                     	UnityEngine.RectTransform               
---@field TxtName                       	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.RectTransform               
---@field ImgFinish                     	UnityEngine.RectTransform               
---@field Imgbg                         	UnityEngine.RectTransform               
---@field BtnGroup                      	UnityEngine.RectTransform               
local UIMainChapterCahpterNode = Class("UIMainChapterCahpterNode")
function UIMainChapterCahpterNode:__init()
    self._curChapterVo = nil
    self._cb = nil
end

function UIMainChapterCahpterNode:__delete()
    self._curChapterVo = nil
    self._cb = nil
end

function UIMainChapterCahpterNode:Awake()
end

function UIMainChapterCahpterNode:Start()
    SetButtonAction(self.BtnGroup, Bind(self, self.OnBtnGroup))
end

function UIMainChapterCahpterNode:FillSelf(vo, cb)
    if not vo then
        return
    end
    self._curChapterVo = vo
    self._cb = cb

    self:FillInfo()
end

function UIMainChapterCahpterNode:FillInfo()
    CfUtils.FillText(self.TxtName, self._curChapterVo.name)
    local status = 1
    local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapter(self._curChapterVo.id)
    local isPass = QuestConfMgr:GetInstance():IsPassChapter(self._curChapterVo.id)
    KTool.SetActive(self.ImgFinish, isPass)
    KTool.SetActive(self.ImgLock, not isUnlock)

    if isUnlock then
        if isPass then
            status = 3
        end
    else
        status = 2
    end
    CfUtils.SetUISwitchImage(self.Imgbg, status)
end

function UIMainChapterCahpterNode:ShowSelect(active)
    KTool.SetActive(self.ImgSelect, active)
end

function UIMainChapterCahpterNode:OnBtnGroup()
    if self._cb then
        self._cb()
    end
end

function UIMainChapterCahpterNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMainChapterCahpterNode